import {useEffect} from 'react'
import {Button, Label, RelativeTime, Text, Truncate} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import type {ImageDefinition, ImageVersion} from '../types/types'
import styles from '../styles/components/CustomImageVersionsTable.module.css'

interface CustomImageVersionsTableProps {
  customImage: ImageDefinition
  customImageVersions: ImageVersion[]
}

export function CustomImageVersionsTable(props: CustomImageVersionsTableProps) {
  // id generated for DataTable
  const customImageVersionsWithIds = props.customImageVersions.map(version => ({
    ...version,
    id: `${version.imageDefinitionId}-${version.version}`,
  }))

  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  return (
    <div>
      <Table.Container>
        {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
        <Table.Title as="h2" id="customer-images">
          Image Versions ({customImageVersionsWithIds.length})
        </Table.Title>
        <Table.Actions>
          {props.customImage.latestVersion && (
            <Button variant="default" size="small" disabled>
              Latest version: <strong>{props.customImage.latestVersion}</strong>
            </Button>
          )}
        </Table.Actions>
        <DataTable
          data={customImageVersionsWithIds}
          columns={[
            {
              header: 'Version',
              field: 'version',
              renderCell: row => {
                return (
                  <Text as="span" weight="normal">
                    {row.version} {row.version === props.customImage.latestVersion && <Label>Latest</Label>}
                  </Text>
                )
              },
            },
            {
              header: 'State',
              field: 'state',
            },
            {
              header: 'State Details',
              field: 'stateDetails',
              renderCell: row => {
                const details = row.stateDetails || 'N/A'
                return (
                  <Truncate className={styles.tableCellEllipsis} title={details}>
                    {details}
                  </Truncate>
                )
              },
            },
            {
              header: 'SizeGB',
              field: 'sizeGb',
            },
            {
              header: 'Created At',
              field: 'createdAt',
              renderCell: row => {
                return <RelativeTime date={new Date(row.createdAt)} prefix="" />
              },
            },
            {
              header: 'Last Used At',
              field: 'lastUsedAt',
              renderCell: row => {
                return row.lastUsedAt ? <RelativeTime date={new Date(row.lastUsedAt)} prefix="" /> : 'Never'
              },
            },
          ]}
        />
      </Table.Container>
    </div>
  )
}
