import {useEffect} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import type {CustomImageVersionListPagePayload} from '../types/payloads'
import {CustomImageBreadcrumbs} from '../components/CustomImageBreadcrumbs'
import {CustomImageDetailsView} from '../components/CustomImageDetailsView'
import {customImageVersionsRoute} from './custom-images-details-route'
import {customImageVersionsEnterpriseRoute} from './custom-images-details-enterprise-route'

export function CustomImageVersionsPageEntrypointForOrg() {
  const {data: payload} = useRouteQuery(customImageVersionsRoute, 'mainQuery')
  return <CustomImageVersionsListPage payload={payload} />
}

export function CustomImageVersionsPageEntrypointForEnterprise() {
  const {data: payload} = useRouteQuery(customImageVersionsEnterpriseRoute, 'mainQuery')
  return <CustomImageVersionsListPage payload={payload} />
}

function CustomImageVersionsListPage({payload}: {payload: CustomImageVersionListPagePayload}) {
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  return (
    <>
      <CustomImageBreadcrumbs imageDefinition={payload.imageDefinition} baseUrl={payload.baseUrl} />
      <CustomImageDetailsView
        imageDefinition={payload.imageDefinition}
        imageVersions={payload.imageVersions}
        runnerGroup={payload.runnerGroup}
      />
    </>
  )
}
